<template><div class="app-container"><el-alert title="绑定历史用于追踪设备从谁绑定、何时解绑；后台仅查询，不直接修改历史。" type="info" :closable="false" style="margin-bottom:16px"/><div class="filter-container"><el-input v-model="query.userId" placeholder="用户ID" clearable style="width:140px"/><el-input v-model="query.deviceSn" placeholder="设备编号" clearable style="width:200px"/><el-select v-model="query.status" clearable placeholder="状态"><el-option label="已绑定" value="ACTIVE"/><el-option label="已解绑" value="UNBOUND"/></el-select><el-button type="primary" @click="load">查询</el-button></div><el-table v-loading="loading" :data="list" border><el-table-column prop="bindNo" label="绑定编号" min-width="170"/><el-table-column prop="deviceSn" label="设备编号" min-width="160"/><el-table-column prop="deviceModel" label="型号"/><el-table-column prop="userName" label="绑定用户"/><el-table-column prop="userId" label="用户ID"/><el-table-column prop="bindSource" label="来源"/><el-table-column prop="bindTime" label="绑定时间" min-width="160"/><el-table-column prop="unbindTime" label="解绑时间" min-width="160"/><el-table-column prop="status" label="状态"/></el-table></div></template><script>import{getJkHealthBindList}from'@/api/jkBusiness';export default{data(){return{query:{page:1,limit:20},list:[],loading:false}},created(){this.load()},methods:{rows(r){return(r&&r.list)||(r&&r.data&&r.data.list)||r.data||r||[]},load(){this.loading=true;getJkHealthBindList(this.query).then(r=>this.list=this.rows(r)).finally(()=>this.loading=false)}}}</script>